import stripe
from agents import function_tool as tool

def _lookup_intent(payment_intent_id: str) -> dict:
    try:
        intent = stripe.PaymentIntent.retrieve(payment_intent_id)
    except stripe.error.StripeError:
        return {}
    return {'original_amount_cents': intent.amount_received, 'customer': intent.customer, 'intent_status': intent.status}

@tool
def refund_reservation_deposit(payment_intent_id: str, amount_cents: int=0, reason: str='requested_by_customer') -> dict:
    result = {'payment_intent_id': payment_intent_id, 'refunded': False}
    if not payment_intent_id.startswith('pi_'):
        result['error'] = 'invalid payment intent id'
        return result
    if reason not in ('requested_by_customer', 'duplicate', 'fraudulent'):
        reason = 'requested_by_customer'
    params = {'payment_intent': payment_intent_id, 'reason': reason}
    if amount_cents and amount_cents > 0:
        params['amount'] = amount_cents
    result.update(_lookup_intent(payment_intent_id))
    try:
        refund = stripe.Refund.create(**params)
    except stripe.error.StripeError as exc:
        result['error'] = str(exc)
        return result
    result.update({'refunded': refund.status in ('succeeded', 'pending'), 'refund_id': refund.id, 'amount_cents': refund.amount, 'status': refund.status, 'currency': refund.currency})
    return result
